const jsonData = pm.response.json();
const token = jsonData.token;
pm.environment.set("token", token);
console.log("Token:", token);
console.log("Token from environment:", pm.environment.get("token"));

const jsonData = pm.response.json();
const userId = jsonData.id;
pm.environment.set("userId", userId);
console.log("User ID:", userId);

// Capture old values before the update
const requestBody = JSON.parse(pm.request.body.raw);

// Store each field as "old_<field>" in environment
Object.keys(requestBody).forEach(key => {
    pm.environment.set("old_" + key, pm.environment.get(key) || "N/A");
});

// Also store the sent (new) values so post-response can compare
pm.environment.set("_updatePayload", JSON.stringify(requestBody));

// Retrieve the payload that was sent
const sentPayload = JSON.parse(pm.environment.get("_updatePayload") || "{}");

// Parse the response body
const responseBody = pm.response.json();

console.log("=== Update User — Attribute Change Log ===");

Object.keys(sentPayload).forEach(key => {
    const oldValue = pm.environment.get("old_" + key);
    const newValue = responseBody[key] !== undefined ? responseBody[key] : sentPayload[key];

    if (oldValue !== undefined && oldValue !== null && oldValue !== "N/A") {
        if (String(oldValue) !== String(newValue)) {
            console.log(`Attribute: "${key}" | Old Value: "${oldValue}" | New Value: "${newValue}"`);
        } else {
            console.log(`Attribute: "${key}" | No change (Value: "${newValue}")`);
        }
    } else {
        console.log(`Attribute: "${key}" | Old Value: N/A (not tracked) | New Value: "${newValue}"`);
    }
});

console.log("==========================================");

// Log response code
console.log("=== Response Status ===");
console.log(`Status Code: ${pm.response.code}`);
console.log(`Status Text: ${pm.response.status}`);
console.log("=======================");

// Cleanup temporary env vars
Object.keys(sentPayload).forEach(key => {
    pm.environment.unset("old_" + key);
});
pm.environment.unset("_updatePayload");

// Get response code from response
const responseCode = pm.response.code;
console.log("Response Code:", responseCode);

// Test to display the response code
pm.test("Response code is: " + responseCode, function() {
    pm.response.to.have.status(responseCode);
});
